cedar:
@id("permit-effective-capability")
@reason("{capability} is delegated in this session and permitted for {useCase}")
@control("CTL-CAP-001")
permit (
  principal is Betsee::Agent,
  action in Betsee::Action::"agent_action",
  resource
)
when {
  context.session.delegated.contains(context.capability) &&
  context.session.useCase.permitted.contains(context.capability)
};

@id("forbid-capability-not-delegated")
@reason("{capability} was not delegated to the agent in this session")
@control("CTL-CAP-001")
forbid (principal, action in Betsee::Action::"agent_action", resource)
unless { context.session.delegated.contains(context.capability) };

@id("forbid-capability-not-permitted-for-use-case")
@reason("organization policy does not permit {capability} for {useCase}")
@control("CTL-CAP-001")
forbid (principal, action in Betsee::Action::"agent_action", resource)
unless { context.session.useCase.permitted.contains(context.capability) };

// Fails closed if the Gateway ever builds a request whose action and capability disagree.

@id("forbid-capability-action-mismatch")
@reason("the requested action does not match the capability being checked")
@control("CTL-POL-002")
forbid (principal, action in Betsee::Action::"agent_action", resource)
unless {
  (action == Betsee::Action::"crm.read" && context.capability == Betsee::Capability::"crm.read") ||
  (action == Betsee::Action::"tickets.read" && context.capability == Betsee::Capability::"tickets.read") ||
  (action == Betsee::Action::"files.read" && context.capability == Betsee::Capability::"files.read") ||
  (action == Betsee::Action::"tickets.write" && context.capability == Betsee::Capability::"tickets.write") ||
  (action == Betsee::Action::"memory.write" && context.capability == Betsee::Capability::"memory.write") ||
  (action == Betsee::Action::"email.send" && context.capability == Betsee::Capability::"email.send") ||
  (action == Betsee::Action::"payments.transfer" && context.capability == Betsee::Capability::"payments.transfer") ||
  (action == Betsee::Action::"shell.exec" && context.capability == Betsee::Capability::"shell.exec") ||
  (action == Betsee::Action::"agent.message" && context.capability == Betsee::Capability::"agent.message") ||
  (action == Betsee::Action::"llm.complete" && context.capability == Betsee::Capability::"llm.complete") ||
  (action == Betsee::Action::"files.write" && context.capability == Betsee::Capability::"files.write") ||
  (action == Betsee::Action::"web.egress" && context.capability == Betsee::Capability::"web.egress") ||
  (action == Betsee::Action::"runtime.unmapped" && context.capability == Betsee::Capability::"runtime.unmapped") ||
  (action == Betsee::Action::"model.load" && context.capability == Betsee::Capability::"model.load")
};

@id("forbid-session-not-bound-to-agent")
@reason("the session does not belong to the calling agent")
@control("CTL-ID-001")
forbid (principal, action in Betsee::Action::"agent_action", resource)
unless { context.session.agent == principal };

@id("forbid-agent-not-active")
@reason("the agent is quarantined or suspended")
@control("CTL-ID-002")
forbid (principal is Betsee::Agent, action in Betsee::Action::"agent_action", resource)
unless { principal.state == "active" };

@id("forbid-session-not-active")
@reason("the session is closed, revoked or expired")
@control("CTL-ID-003")
forbid (principal, action in Betsee::Action::"agent_action", resource)
unless {
  context.session.status == "active" &&
  context.now < context.session.expiresAt
};

@id("forbid-session-human-not-active")
@reason("the human behind the session is no longer active")
@control("CTL-ID-004")
forbid (principal, action in Betsee::Action::"agent_action", resource)
unless { context.session.human.active };

@id("forbid-resource-above-session-tier")
@reason("the resource is {resource.tier}, the session ceiling is {session.tierCeiling}")
@control("CTL-TIER-001")
forbid (
  principal,
  action in Betsee::Action::"agent_action",
  resource is Betsee::Resource
)
when { resource.tier > context.session.tierCeiling };

// No write-down: once a session has read data at tier T, it may not write or send to a
// destination labelled below T. session.taint is the highest tier read so far.

@id("forbid-write-down")
@reason("the session has read {session.taint} data and the destination is {recipient.tier}")
@control("CTL-TIER-002")
forbid (
  principal,
  action in [Betsee::Action::"write", Betsee::Action::"egress"],
  resource is Betsee::Resource
)
when { resource.tier < context.session.taint };

@id("forbid-model-below-session-taint")
@reason("the session holds {session.taint} data, above this model's clearance")
@control("CTL-TIER-003")
forbid (
  principal,
  action == Betsee::Action::"llm.complete",
  resource is Betsee::Model
)
when { resource.maxTier < context.session.taint };

@id("forbid-delegated-execution-mismatch")
@reason("delegated execution applies only to resources the agent runtime reaches")
@control("CTL-RT-001")
forbid (
  principal,
  action in Betsee::Action::"agent_action",
  resource is Betsee::Resource
)
when { (context has runtime) != (resource in Betsee::Connector::"agent-runtime") };

@id("forbid-agent-runtime-egress")
@reason("the agent runtime has no network egress, so {capability} is denied")
@control("CTL-RT-001")
forbid (principal, action in Betsee::Action::"egress", resource)
when { context has runtime };

@id("forbid-runtime-unmapped-tool")
@reason("this runtime tool maps to no Betsee capability, so it is denied by default")
@control("CTL-RT-001")
forbid (principal, action == Betsee::Action::"runtime.unmapped", resource);

// A command or a folder search can read more than its named resource; the Gateway resolves that
// scope to the highest tier it covers.

@id("forbid-scope-above-session-tier")
@reason("the request reads {scope.tier} content, the session ceiling is {session.tierCeiling}")
@control("CTL-TIER-001")
forbid (principal, action in Betsee::Action::"agent_action", resource)
when { context has scopeTier && context.scopeTier > context.session.tierCeiling };

@id("forbid-mcp-call-without-tool")
@reason("the call does not name a pinned MCP tool")
@control("CTL-TOOL-001")
forbid (principal, action in Betsee::Action::"mcp", resource)
unless { context has toolCall || context has runtime };

@id("forbid-tool-descriptor-drift")
@reason("the descriptor of {tool} no longer matches its reviewed pin")
@control("CTL-TOOL-001")
forbid (principal, action in Betsee::Action::"agent_action", resource)
when {
  context has toolCall &&
  context.toolCall.tool.pinnedDescriptorHash != context.toolCall.observedDescriptorHash
};

@id("forbid-command-not-validated")
@reason("the command matches no validated template")
@control("CTL-EXEC-001")
forbid (principal, action == Betsee::Action::"shell.exec", resource)
unless { context has command && context.command.valid };

@id("forbid-a2a-peer-not-allowed")
@reason("messages to {receiver} are not allowed in {useCase}")
@control("CTL-A2A-001")
forbid (
  principal,
  action == Betsee::Action::"agent.message",
  resource is Betsee::Agent
)
unless { context.session.useCase.peers.contains(resource) };

@id("forbid-a2a-receiver-not-active")
@reason("{receiver} is quarantined or suspended")
@control("CTL-A2A-001")
forbid (
  principal,
  action == Betsee::Action::"agent.message",
  resource is Betsee::Agent
)
unless { resource.state == "active" };

@id("forbid-a2a-receiver-below-session-taint")
@reason("{receiver} is cleared below the {session.taint} data this session holds")
@control("CTL-A2A-002")
forbid (
  principal,
  action == Betsee::Action::"agent.message",
  resource is Betsee::Agent
)
when { resource.clearance < context.session.taint };

// A message is not a delegation: the sender cannot ask for a capability outside its own
// effective capability set.

@id("forbid-a2a-capability-escalation")
@reason("the message asks for a capability the sender does not hold, and a message is not a delegation")
@control("CTL-A2A-003")
forbid (principal, action == Betsee::Action::"agent.message", resource)
unless {
  context has requestedCapability &&
  context.session.delegated.contains(context.requestedCapability) &&
  context.session.useCase.permitted.contains(context.requestedCapability)
};

@id("permit-input-from-session-human")
@reason("the message passed the input filter for {useCase}")
@control("CTL-IN-001")
permit (
  principal is Betsee::Human,
  action == Betsee::Action::"input.submit",
  resource is Betsee::AgentSession
)
when { resource.human == principal };

@id("forbid-input-not-session-human")
@reason("only the human who started this session can write to its agent")
@control("CTL-IN-001")
forbid (principal, action == Betsee::Action::"input.submit", resource is Betsee::AgentSession)
unless { resource.human == principal };

@id("forbid-input-session-not-active")
@reason("the session is closed, revoked or expired")
@control("CTL-ID-003")
forbid (principal, action == Betsee::Action::"input.submit", resource is Betsee::AgentSession)
unless { resource.status == "active" && context.now < resource.expiresAt };

@id("forbid-input-human-not-active")
@reason("the human is no longer active")
@control("CTL-ID-004")
forbid (principal is Betsee::Human, action == Betsee::Action::"input.submit", resource)
unless { principal.active };

@id("forbid-input-payment-card")
@reason("the message contains a payment card number")
@control("CTL-IN-001")
forbid (principal, action == Betsee::Action::"input.submit", resource)
when { context.detected.contains("payment_card") };

@id("forbid-input-iban")
@reason("the message contains a bank account number (IBAN)")
@control("CTL-IN-001")
forbid (principal, action == Betsee::Action::"input.submit", resource)
when { context.detected.contains("iban") };

@id("forbid-input-pesel")
@reason("the message contains a PESEL national identification number")
@control("CTL-IN-001")
forbid (principal, action == Betsee::Action::"input.submit", resource)
when { context.detected.contains("pesel") };

@id("forbid-input-secret")
@reason("the message contains an API key or a private key")
@control("CTL-IN-001")
forbid (principal, action == Betsee::Action::"input.submit", resource)
when { context.detected.contains("secret") };

@id("forbid-input-email")
@reason("the message contains an email address, which this use case's profile blocks")
@control("CTL-IN-001")
forbid (principal, action == Betsee::Action::"input.submit", resource)
when { context.detected.contains("email") };

@id("forbid-input-phone")
@reason("the message contains a phone number, which this use case's profile blocks")
@control("CTL-IN-001")
forbid (principal, action == Betsee::Action::"input.submit", resource)
when { context.detected.contains("phone") };

@id("forbid-input-resource-above-tier")
@reason("the message names a resource above the session ceiling of {session.tierCeiling}")
@control("CTL-IN-001")
forbid (principal, action == Betsee::Action::"input.submit", resource)
when { context.detected.contains("resource_above_tier") };

@id("analyzer-input-malicious")
@reason("semantic analysis judged the message an injection or jailbreak attempt")
@control("CTL-AI-001")
forbid (principal, action == Betsee::Action::"input.submit", resource)
when { context has analysis && context.analysis.verdict == "malicious" };

@id("permit-file-transfer-by-session-human")
@reason("the file passed the Betsee file scan for {useCase}")
@control("CTL-FILE-001")
permit (
  principal is Betsee::Human,
  action in Betsee::Action::"file_transfer",
  resource is Betsee::Resource
)
when {
  context.session.human == principal &&
  resource in Betsee::Connector::"agent-runtime"
};

@id("forbid-file-not-session-human")
@reason("only the human who started this session can move files in or out of its workspace")
@control("CTL-FILE-001")
forbid (principal, action in Betsee::Action::"file_transfer", resource)
unless { context.session.human == principal };

@id("forbid-file-outside-agent-runtime")
@reason("files move only in and out of the agent runtime workspace")
@control("CTL-FILE-001")
forbid (principal, action in Betsee::Action::"file_transfer", resource is Betsee::Resource)
unless { resource in Betsee::Connector::"agent-runtime" };

@id("forbid-file-session-not-active")
@reason("the session is closed, revoked or expired")
@control("CTL-ID-003")
forbid (principal, action in Betsee::Action::"file_transfer", resource)
unless {
  context.session.status == "active" &&
  context.now < context.session.expiresAt
};

@id("forbid-file-above-session-tier")
@reason("the file is labelled above the session ceiling of {session.tierCeiling}")
@control("CTL-TIER-001")
forbid (principal, action in Betsee::Action::"file_transfer", resource)
when { context.tier > context.session.tierCeiling };

@id("forbid-file-payment-card")
@reason("the file contains a payment card number")
@control("CTL-IN-001")
forbid (principal, action in Betsee::Action::"file_transfer", resource)
when { context.detected.contains("payment_card") };

@id("forbid-file-iban")
@reason("the file contains a bank account number (IBAN)")
@control("CTL-IN-001")
forbid (principal, action in Betsee::Action::"file_transfer", resource)
when { context.detected.contains("iban") };

@id("forbid-file-pesel")
@reason("the file contains a PESEL national identification number")
@control("CTL-IN-001")
forbid (principal, action in Betsee::Action::"file_transfer", resource)
when { context.detected.contains("pesel") };

@id("forbid-file-secret")
@reason("the file contains an API key or a private key")
@control("CTL-IN-001")
forbid (principal, action in Betsee::Action::"file_transfer", resource)
when { context.detected.contains("secret") };

@id("forbid-file-resource-above-tier")
@reason("the file names a resource above the session ceiling of {session.tierCeiling}")
@control("CTL-IN-001")
forbid (principal, action in Betsee::Action::"file_transfer", resource)
when { context.detected.contains("resource_above_tier") };

@id("forbid-file-executable")
@reason("the file is an executable or a script")
@control("CTL-FILE-001")
forbid (principal, action in Betsee::Action::"file_transfer", resource)
when { context.detected.contains("executable") };

@id("forbid-file-malware-test")
@reason("the file carries the EICAR anti-malware test signature")
@control("CTL-FILE-001")
forbid (principal, action in Betsee::Action::"file_transfer", resource)
when { context.detected.contains("malware_test") };

@id("forbid-file-unscannable")
@reason("the file has no text Betsee can scan, so it cannot be checked")
@control("CTL-FILE-001")
forbid (principal, action in Betsee::Action::"file_transfer", resource)
when { context.detected.contains("unscannable") };

@id("forbid-file-type-not-allowed")
@reason("Betsee accepts text, PDF, Word and Excel files only")
@control("CTL-FILE-001")
forbid (principal, action in Betsee::Action::"file_transfer", resource)
when { context.detected.contains("type_not_allowed") };

@id("forbid-file-oversize")
@reason("the file is larger than the 8 MiB Betsee scans")
@control("CTL-FILE-001")
forbid (principal, action in Betsee::Action::"file_transfer", resource)
when { context.detected.contains("oversize") };

@id("forbid-known-exploit-signature")
@reason("the request matches a signature of a known exploit")
@control("CTL-SIG-001")
forbid (principal, action in Betsee::Action::"agent_action", resource)
when { context has threat && context.threat.block };

@id("review-exploit-signature")
@reason("the request matches a signature that needs a person to review it")
@control("CTL-SIG-001")
@outcome("require_approval")
forbid (principal, action in Betsee::Action::"agent_action", resource)
when { context has threat && context.threat.review }
unless { context.approval.granted };

@id("forbid-input-exploit-signature")
@reason("the message matches a signature of a known exploit")
@control("CTL-SIG-001")
forbid (principal, action == Betsee::Action::"input.submit", resource)
when { context has threat && context.threat.block };

@id("forbid-file-exploit-signature")
@reason("the file matches a signature of a known exploit")
@control("CTL-SIG-001")
forbid (principal, action in Betsee::Action::"file_transfer", resource)
when { context has threat && context.threat.block };

@id("forbid-file-unsafe-deserialization")
@reason("the file is a pickle that would run code when loaded")
@control("CTL-FILE-002")
forbid (principal, action in Betsee::Action::"file_transfer", resource)
when { context.detected.contains("unsafe_deserialization") };

@id("forbid-file-model-code-execution")
@reason("the file is a model whose metadata or layers would run code when loaded")
@control("CTL-FILE-002")
forbid (principal, action in Betsee::Action::"file_transfer", resource)
when { context.detected.contains("model_code_execution") };

@id("forbid-model-not-allowlisted")
@reason("the model is not on the organization's model allowlist")
@control("CTL-MODEL-001")
forbid (principal, action == Betsee::Action::"llm.complete", resource)
when { context has modelAllowed && !context.modelAllowed };

@id("forbid-prompt-sensitive-data")
@reason("the prompt carries data this use case's profile does not let a model see")
@control("CTL-IN-001")
forbid (principal, action == Betsee::Action::"llm.complete", resource)
when { context has detected && !context.detected.isEmpty() };

@id("forbid-model-revision-not-pinned")
@reason("a model must be pinned to a full commit hash, not a branch or tag")
@control("CTL-SUP-001")
forbid (principal, action == Betsee::Action::"model.load", resource)
when { context has modelCheck && !context.modelCheck.pinned };

@id("forbid-model-remote-code")
@reason("loading a model must not run code from its repository (trust_remote_code)")
@control("CTL-SUP-001")
forbid (principal, action == Betsee::Action::"model.load", resource)
when { context has modelCheck && context.modelCheck.trustRemoteCode };

@id("forbid-model-unsafe-format")
@reason("the model ships weights in a format that can run code when loaded; use safetensors or GGUF")
@control("CTL-SUP-001")
forbid (principal, action == Betsee::Action::"model.load", resource)
when { context has modelCheck && context.modelCheck.unsafeFormat };

@id("forbid-model-org-typosquat")
@reason("the model's publisher name imitates a trusted publisher")
@control("CTL-SUP-001")
forbid (principal, action == Betsee::Action::"model.load", resource)
when { context has modelCheck && context.modelCheck.typosquat };

@id("forbid-model-org-not-allowed")
@reason("the model's publisher is not on the organization's list of trusted publishers")
@control("CTL-SUP-001")
forbid (principal, action == Betsee::Action::"model.load", resource)
when { context has modelCheck && !context.modelCheck.orgAllowed };

@id("forbid-model-known-bad")
@reason("the model repository is on the threat feed as malicious")
@control("CTL-SUP-001")
forbid (principal, action == Betsee::Action::"model.load", resource)
when { context has modelCheck && context.modelCheck.knownBad };

@id("forbid-model-load-without-check")
@reason("the Gateway could not check this model request")
@control("CTL-SUP-001")
forbid (principal, action == Betsee::Action::"model.load", resource)
unless { context has modelCheck };

@id("forbid-budget-exceeded")
@reason("this action would exceed the session budget")
@control("CTL-RUN-001")
forbid (principal, action in Betsee::Action::"agent_action", resource)
when { context.session.spentCents + context.costCents > context.session.budgetCents };

@id("forbid-token-budget-exceeded")
@reason("this model call could exceed the session's token budget")
@control("CTL-RUN-005")
forbid (principal, action in Betsee::Action::"agent_action", resource)
when {
  context has tokens &&
  context.session has tokenBudget &&
  context.session has tokensUsed &&
  context.session.tokensUsed + context.tokens > context.session.tokenBudget
};

@id("forbid-rate-exceeded")
@reason("the agent exceeded the action rate allowed for {useCase}")
@control("CTL-RUN-002")
forbid (principal, action in Betsee::Action::"agent_action", resource)
when { context.actionsLastMinute > context.session.useCase.maxActionsPerMinute };

@id("approval-required-by-use-case")
@reason("approval is required for {capability} in {useCase}")
@control("CTL-APR-001")
@outcome("require_approval")
forbid (principal, action in Betsee::Action::"agent_action", resource)
when { context.session.useCase.approvalRequired.contains(context.capability) }
unless { context.approval.granted };

@id("step-up-required-by-use-case")
@reason("{capability} in {useCase} needs an approver with a fresh OTP")
@control("CTL-APR-002")
@outcome("require_step_up")
forbid (principal, action in Betsee::Action::"agent_action", resource)
when { context.session.useCase.stepUpRequired.contains(context.capability) }
unless { context.approval.stepUp };

@id("forbid-payment-without-amount")
@reason("the transfer request carries no valid amount")
@control("CTL-APR-003")
forbid (principal, action == Betsee::Action::"payments.transfer", resource)
unless { context has amountCents && context.amountCents > 0 };

@id("approval-payment-above-threshold")
@reason("the transfer of {amount} is above the {threshold} approval threshold")
@control("CTL-APR-003")
@outcome("require_approval")
forbid (principal, action == Betsee::Action::"payments.transfer", resource)
when {
  context has amountCents &&
  context.amountCents > context.session.useCase.approvalThresholdCents
}
unless { context.approval.granted };

@id("step-up-payment-above-threshold")
@reason("a transfer above {threshold} needs an approver with a fresh OTP")
@control("CTL-APR-003")
@outcome("require_step_up")
forbid (principal, action == Betsee::Action::"payments.transfer", resource)
when {
  context has amountCents &&
  context.amountCents > context.session.useCase.approvalThresholdCents
}
unless { context.approval.stepUp };

// After a session ingested untrusted content (an inbound ticket, another agent's message), a
// high-impact action needs a human.

@id("approval-high-impact-after-untrusted-input")
@reason("the session has read untrusted input, so {capability} needs a human")
@control("CTL-PROV-001")
@outcome("require_approval")
forbid (principal, action in Betsee::Action::"high_impact", resource)
when { context.session.untrustedInput }
unless { context.approval.granted };

@id("analyzer-malicious")
@reason("semantic analysis judged the request malicious")
@control("CTL-AI-001")
forbid (principal, action in Betsee::Action::"agent_action", resource)
when { context has analysis && context.analysis.verdict == "malicious" };

@id("analyzer-suspicious")
@reason("semantic analysis found instructions inside the request's data; a person must look first")
@control("CTL-AI-001")
@outcome("require_approval")
forbid (principal, action in Betsee::Action::"agent_action", resource)
when { context has analysis && context.analysis.verdict == "suspicious" }
unless { context.approval.granted };

@id("permit-session-delegation-within-entitlements")
@reason("the delegation stays within the human's entitlements and {useCase}")
@control("CTL-DEL-001")
permit (
  principal is Betsee::Human,
  action == Betsee::Action::"session.create",
  resource is Betsee::Agent
)
when {
  principal.active &&
  principal.entitlements.containsAll(context.delegated) &&
  context.useCase.permitted.containsAll(context.delegated)
};

@id("forbid-session-tier-above-ceiling")
@reason("the requested session ceiling is above the human's clearance, the ceiling of {useCase} or the agent's clearance")
@control("CTL-DEL-002")
forbid (
  principal is Betsee::Human,
  action == Betsee::Action::"session.create",
  resource is Betsee::Agent
)
when {
  context.tierCeiling > principal.clearance ||
  context.tierCeiling > context.useCase.tierCeiling ||
  context.tierCeiling > resource.clearance
};

@id("forbid-session-agent-not-registered-for-use-case")
@reason("the agent is not registered for {useCase}")
@control("CTL-DEL-003")
forbid (principal, action == Betsee::Action::"session.create", resource is Betsee::Agent)
unless { context.useCase.agents.contains(resource) };

@id("forbid-session-for-inactive-agent")
@reason("the agent is quarantined or suspended")
@control("CTL-ID-002")
forbid (principal, action == Betsee::Action::"session.create", resource is Betsee::Agent)
unless { resource.state == "active" };

// Mirrors of the permit so a refused delegation names the side that failed.

@id("forbid-session-delegation-exceeds-human-entitlements")
@reason("the delegation includes capabilities the human does not hold")
@control("CTL-DEL-001")
forbid (principal is Betsee::Human, action == Betsee::Action::"session.create", resource)
unless { principal.entitlements.containsAll(context.delegated) };

@id("forbid-session-delegation-exceeds-use-case")
@reason("the delegation includes capabilities {useCase} does not permit")
@control("CTL-DEL-001")
forbid (principal, action == Betsee::Action::"session.create", resource)
